import <hashmap>;
fn main() -> i32 {
    dec rw round: i32 = 0;
    while round < 8 {
        dec rw map = std::hashmap_new<i32, i32>();
        dec rw i: i32 = 0;
        while i < 1500 { map.insert(i * 1, i); i = i + 1; }
        if map.len() != (1500 as u64) { return 1; }
        round = round + 1;
    }
    return 0;
}

